def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load()
def f(I):
    H=len(I);W=len(I[0])
    cnt=Counter(x for row in I for x in row)
    bg=max(cnt,key=lambda v:cnt[v]);mark=min(cnt,key=lambda v:cnt[v])
    out=[row[:] for row in I];seen=set()
    cells=[(r,c) for r in range(H) for c in range(W) if I[r][c]==mark]
    for cell in sorted(cells):
        if cell in seen:continue
        q=deque([cell]);seen.add(cell);grp=[]
        while q:
            x=q.popleft();grp.append(x)
            for dr in(-1,0,1):
                for dc in(-1,0,1):
                    y=(x[0]+dr,x[1]+dc)
                    if 0<=y[0]<H and 0<=y[1]<W and I[y[0]][y[1]]==mark and y not in seen:
                        seen.add(y);q.append(y)
        rs=[p[0] for p in grp];cs=[p[1] for p in grp]
        r0,r1,cc0,cc1=min(rs),max(rs),min(cs),max(cs)
        if len(grp)>=2:
            rr0,rr1,ccm0,ccm1=r0-1,r1+1,cc0-1,cc1+1
            for r in range(rr0,rr1+1):
                for c in range(ccm0,ccm1+1):
                    if r in (rr0,rr1) or c in (ccm0,ccm1):
                        out[r][c]=3
    return out
for p in ('Demo pair 1','Demo pair 2'):
    print(p, f(G[p+' input'])==G[p+' output'])

