def comps_of(I,diag=True):
    H=len(I);W=len(I[0]);seen=set();res=[]
    cells=[(r,c) for r in range(H) for c in range(W) if I[r][c]==9] if 9 in [v for row in I for v in row] else None
    marks=set(v for row in I for v in row)
    minority=min(marks,key=lambda v:(sum(row.count(v) for row in I)))
    cells=[(r,c) for r in range(H) for c in range(W) if I[r][c]==minority]
    seen=set()
    for cell in sorted(cells):
        if cell in seen:continue
        q=deque([cell]);seen.add(cell);grp=[]
        while q:
            x=q.popleft();grp.append(x)
