                for dc in(-1,0,1):
                    y=(x[0]+dr,x[1]+dc)
                    if 0<=y[0]<len(I) and 0<=y[1]<len(I[0]) and I[y[0]][y[1]]==minority and y not in seen:
                        seen.add(y);q.append(y)
        res.append(sorted(grp))
    return res
