        if cell in seen:continue
        q=deque([cell]);seen.add(cell);grp=[]
        while q:
            x=q.popleft();grp.append(x)
            for dr in(-1,0,1):
                for dc in(-1,0,1):
                    y=(x[0]+dr,x[1]+dc)
                    if 0<=y[0]<H and 0<=y[1]<W and I[y[0]][y[1]]==mark and y not in seen:
